44	document.addEventListener("keydown", function (event) {
45	  // Skip during text input.
46	  if (event.target.tagName === "INPUT" && event.target.type === "text") {
47	    return;
48	  }
49	
50	  const keybindings = {
51	    " ": "reveal", // Space
52	    u: "undo",
53	    1: "forgot",
54	    2: "hard",
55	    3: "good",
56	    4: "easy",
57	  };
58	
59	  if (keybindings[event.key]) {
60	    // Ignore modifiers.
61	    if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) {
62	      return;
63	    }
64	    event.preventDefault();
65	    const id = keybindings[event.key];
66	    const node = document.getElementById(id);
